cat > Program.cs << 'EOF'
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild("/tmp/sv-bbadb973669d42bda166866888c57519/build.binlog");
Console.WriteLine($"Build succeeded: {build.Succeeded}");
Console.WriteLine();

// Find all errors
var errors = new List<(string project, string code, string file, int line, string message)>();
build.VisitAllChildren<Error>(error => {
    var project = "";
    var node = error.Parent;
    while (node != null) {
        if (node is Project p) { project = p.Name; break; }
        node = node.Parent;
    }
    errors.Add((project, error.Code ?? "", error.File ?? "", error.LineNumber, error.Text ?? ""));
});

Console.WriteLine($"Total errors: {errors.Count}");
Console.WriteLine();
foreach (var (project, code, file, line, message) in errors)
{
    Console.WriteLine($"[{project}] {code} at {file}:{line}");
    Console.WriteLine($"  {message}");
    Console.WriteLine();
}
EOF

